WITH funded AS ({{FUNDED}}) SELECT CASE WHEN t.accept_time<b.fb THEN 'before_binding' ELSE 'after_binding' END phase,COUNT(*) transactions,COUNT(DISTINCT b.pmid) accounts,SUM(t.buy_amount) inflow_amount FROM funded b JOIN qm_meta.trade_detail t ON t.user_id=b.pmid AND t.canceled=0 AND t.accept_time>='2026-01-01 00:00:00' AND t.accept_time<'{{CUT}}' AND (t.buy_amount>0 AND ((t.trade_type='wallet.recharge' AND t.extra IN ('by.online','by.offline')) OR (t.trade_type<>'wallet.recharge' AND t.extra='from.card'))) GROUP BY phase
